import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"20、【观】 坤下巽上","description":"周易集注 - 20、【观】 坤下巽上","frontmatter":{"title":"20、【观】 坤下巽上","description":"周易集注 - 20、【观】 坤下巽上"},"headers":[],"relativePath":"zh/classics/jizhu/024.md","filePath":"zh/classics/jizhu/024.md"}'),h={name:"zh/classics/jizhu/024.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_20、【观】-坤下巽上" tabindex="-1">20、【观】 坤下巽上 <a class="header-anchor" href="#_20、【观】-坤下巽上" aria-label="Permalink to “20、【观】 坤下巽上”">​</a></h1><p>观者，有象以示人而为人所观仰也。风行地上，遍触万类，周观之象也。二阳尊上，为下四阴所观，仰观之义也。《序卦》“临者大也，物大然后可观，故受之以观”，所以次临。</p><p>盥者，将祭而洁手也。荐者，奉酒食以荐也。有孚者信也，颙者大头也，仰也。《尔雅》“颙颙”“君之德也”，大头在上之意，仰观君德之意。言祭祀者方洁手而未荐，人皆信而仰之矣，观者必当如是也。自上示下曰观，去声，自下观上曰观，平声。</p><p>《彖》曰：大观在上，顺而巽，中正以观天下，观，盥而不荐，有孚颙若，下观而化也。观天之神道，而四时不忒。圣人以神道设教，而天下服矣。观皆去声，惟下观而化平声。</p><p>以卦体卦德释卦名，又释卦辞，而极言之。顺者心于理无所乖，巽者事于理无所拂。中正即九五，阳大阴小，故曰大观在上，中正则所观之道也。言人君欲为观于天下，必所居者九五大观之位，所具者顺巽之德，而后以我所居之中观天下之不中，所居之正观天下之不正，斯可以为观矣。所以名观，下观而化，故人信而仰之，所以有孚颙若者此也。盥而不荐者神感也，有孚颙若者神应也，此观之所以神也，故以天道、圣人之神道极言而赞之。神者妙不可测，莫知其然之谓。天之神道非有声色，而四时代谢无少差忒。圣人神道设教，亦非有声色，而民自服从，观之神一而已矣。</p><h3 id="《象》曰-风行地上-观-先王以省方观民设教。上观去声-下观平声" tabindex="-1">《象》曰：风行地上，观，先王以省方观民设教。上观去声，下观平声 <a class="header-anchor" href="#《象》曰-风行地上-观-先王以省方观民设教。上观去声-下观平声" aria-label="Permalink to “《象》曰：风行地上，观，先王以省方观民设教。上观去声，下观平声”">​</a></h3><p>省方者，巡狩省视四方也。观民者，观民俗也，即陈诗以观民纳价以观好恶也。设教者，因俗以设教也，如齐之末业，教以农桑，卫之淫风，教以有别是也。风行地上，周及庶物，有历览周遍之象，故以省方体之。坤为方，方之象。巽以申命，设教之象。</p><p>初六，童观，小人无咎，君子咎。观平声</p><p>童者，童稚也。观者，观乎五也。中爻艮为少男，童之象也。初居阳，亦童之象。故二居阴，取女之象。小人者，下民也。本卦阴取下民，阳取君子。无咎者，百姓日用而不知，所以无咎也。君子吝一句，乃足上句之意，故小象不言君子。</p><p>初六当大观在上之时，阴柔在下，去五最远，不能观五中正之德辉，犹童子之识见，不能及远，故有童观之象。然其占在小人则无咎，若君子岂无咎哉!亦可羞吝矣。见在小人则当无咎也。</p><h3 id="《象》曰-初六童观-小人道也。" tabindex="-1">《象》曰：初六童观，小人道也。 <a class="header-anchor" href="#《象》曰-初六童观-小人道也。" aria-label="Permalink to “《象》曰：初六童观，小人道也。”">​</a></h3><p>不能观国之光，小人之道，自是如此。</p><p>六二，窥观，利女贞。观平声</p><p>窥，与窥同，门内窥视也。不出户庭，仅窥一隙之狭者也。曰利女贞，则丈夫非所利矣。中爻艮，门之象也。变坎为隐伏，坎错离为目，目在门内隐伏处，窥视之象也。二本与五相应，但二之前即门，所以窥观。</p><p>六二阴柔，当观之时，居内而观外，不出户庭，而欲观中正之道，不可得矣，故有窥观之象。惟女子则得其正也，故其占如此。</p><h3 id="《象》曰-窥观女贞-亦可丑也。" tabindex="-1">《象》曰：窥观女贞，亦可丑也。 <a class="header-anchor" href="#《象》曰-窥观女贞-亦可丑也。" aria-label="Permalink to “《象》曰：窥观女贞，亦可丑也。”">​</a></h3><p>妇无公事，所知者蚕织;女无是非，所议者酒食。则窥观，乃女子之正道也。丈夫志在四方，宇宙内事乃吾分内事，以丈夫而为女子之观，亦可丑矣。</p><p>六三，观我生进退。观平声</p><p>下爻皆观乎五，三隔四，四已观国之光，三惟观我生而已。我生者，我阴阳相生之正气也，即上九也。为进退，为不果者，巽也。巽有进退之象，故曰观我生进退。</p><p>六三当观之时，隔四不能观国，故有观我生进退之人之象。不言占之凶咎者，阴阳正应，未为失道，所当观者也。</p><h3 id="《象》曰-观我生进退-未失道也。" tabindex="-1">《象》曰：观我生进退，未失道也。 <a class="header-anchor" href="#《象》曰-观我生进退-未失道也。" aria-label="Permalink to “《象》曰：观我生进退，未失道也。”">​</a></h3><p>道者阴阳相应之正道也。</p><p>六四，观国之光，利用宾于王。观平声</p><p>光者，九五阳明在上，被四表，光四方者也。下坤土，国之象。中爻艮，辉光之象。四承五，宾主之象。九五王之象。观国光者，亲炙其盛，快睹其休也。宾者，已仕者朝觐于君，君则宾礼之，未仕而仕进于君，君则宾兴之也。观卦利近不利远，六二中正，又乃正应，乃曰窥观，则不利于远可知矣。</p><p>六四柔顺得正，最近于五，有观光之象，故占者利用宾于王。</p><h3 id="《象》曰-观国之光-尚宾也。" tabindex="-1">《象》曰：观国之光，尚宾也。 <a class="header-anchor" href="#《象》曰-观国之光-尚宾也。" aria-label="Permalink to “《象》曰：观国之光，尚宾也。”">​</a></h3><p>尚谓心志之所尚，言其志意，愿宾于王朝。</p><p>九五，观我生，君子无咎。观去声</p><p>九五上九，生字亦如六三生字，皆我相生之阴阳也。观我生作句，上九相同，观孔子《小象》可见矣。观我生者，观示乎我所生之四阴也，即中正以观天下也。君子无咎对初爻小人无咎言，下四阴爻皆小人，上二阳爻皆君子。小人当仰观乎上，故无咎。君子当观示乎下，故无咎。</p><p>九五为观之主，阳刚中正，以居尊位，下之四阴皆其所观示者也，故有观我生之象。大观在上，君子无咎之道也，故其象占如此。</p><h3 id="《象》曰-观我生-观民也。二观字皆去声" tabindex="-1">《象》曰：观我生，观民也。二观字皆去声 <a class="header-anchor" href="#《象》曰-观我生-观民也。二观字皆去声" aria-label="Permalink to “《象》曰：观我生，观民也。二观字皆去声”">​</a></h3><p>民即下四阴，阴为民之象也，故姤九四曰远民，以初六阴爻也。内卦三阴，远于五，草莽之民也。六四之阴近于五，仕进之民也。九五虽与六二正应，然初三四与九五皆阴阳相生，故曰观我生。观民也即中正以观天下之民也。</p><p>上九，观其生，君子无咎。观去声</p><p>上九虽在观示之上，然本卦九五有天下国家之责，所以九五观示乎诸爻，诸爻仰观乎九五。曰我生者，即大有六五，五阳皆其所有之意。言下四阴，惟我可以观示，他爻不可得而观示之也。若上九不在其位，不任其事，则无观示之责，止因在上位，阴阳相生，义当观其生，是空有观生之位而已，故不曰观我生，而曰观其生者，避五也。是我字甚重，而其字甚轻也。君子无咎者，九五与上九皆阳刚在上，故并君子之无咎也。</p><p>上九以阳刚居观之极，故有观其生之象，亦君子之无咎者，故其象占如此。</p><h3 id="《象》曰-观其生-志未平也。" tabindex="-1">《象》曰：观其生，志未平也。 <a class="header-anchor" href="#《象》曰-观其生-志未平也。" aria-label="Permalink to “《象》曰：观其生，志未平也。”">​</a></h3><p>志者，上九之心志也。平者，均平也，与九五平分，相同一般之意。言周公爻辞，九五观我生，而上九则以其字易我字者，何哉?以上九之心志，不敢与九五同观其民也，故曰志未平也。盖观示乎民，乃人君之事，若上九亦观示乎民，则人臣之权，与人君之权，相为均平而无二矣，岂其理哉。故上九阳刚，虽与五同，不过有观生之位而已，不敢以四阴为我之民，与九五平观示之也。</p>',37)])])}const f=e(h,[["render",t]]);export{_ as __pageData,f as default};
